/**
 * Evidence control for operational vouchers. This is not an emission factor.
 * Amounts below the threshold still calculate.
 */
const HIGH_VALUE_BILL_THRESHOLD_INR = 250000;

const HIGH_VALUE_BILL_POLICY = Object.freeze({
  thresholdInr: HIGH_VALUE_BILL_THRESHOLD_INR,
  consideredAndNotUsedInr: 200000,
  validationScope: 'accounting_connectors',
  smsInValidationScope: false,
  basis: [
    'A CSV or Excel accounting import does not set a supporting-bill hold from the rupee amount.',
    '₹2,50,000 and ₹2,00,000 are not applied to an accounting-file transaction.',
    'The quantity and unit on the imported row are the activity. A missing quantity stays at 0 kg CO2e until that quantity is entered.',
    'Bank SMS ingestion is outside the GHG tool validation scope.'
  ].join(' ')
});

const RELEASED_HIGH_VALUE_BILL_STATUSES = new Set(['verified_active', 'clarified_by_user']);

/** A ₹2,50,000+ voucher that still has no bill and no user clarification. */
const transactionAwaitingHighValueBill = (transaction = {}) => {
  const extracted = transaction?.metadata?.extractedData;
  if (!extracted || extracted.highValueBillRequired !== true) return false;
  const status = String(extracted.highValueBillStatus || 'awaiting_bill');
  return !RELEASED_HIGH_VALUE_BILL_STATUSES.has(status);
};

module.exports = {
  HIGH_VALUE_BILL_THRESHOLD_INR,
  HIGH_VALUE_BILL_POLICY,
  transactionAwaitingHighValueBill
};
