const INVALID_FILENAME_CHARS = /[<>:"/\\|?*\u0000-\u001f]/g;
const SOURCE_EXTENSION = /\.(xlsx|xls|xlsm|csv)$/i;
const PLACEHOLDER_NAME = /^(?:import|api sync)$/i;

const uploadAuditDownloadFilename = (originalName, fallback) => {
  const fallbackName = String(fallback || '').trim() || 'transaction_audit_upload.xlsx';
  const raw = String(originalName || '').replace(/[\r\n]/g, ' ').trim();
  if (!raw || PLACEHOLDER_NAME.test(raw)) return fallbackName;

  const stem = raw
    .replace(SOURCE_EXTENSION, '')
    .replace(INVALID_FILENAME_CHARS, '_')
    .replace(/[. ]+$/g, '')
    .trim()
    .slice(0, 180);
  if (!stem) return fallbackName;
  if (/_Audit$/i.test(stem)) return `${stem}.xlsx`;
  return `${stem}_Audit.xlsx`;
};

module.exports = { uploadAuditDownloadFilename };
