import React, { useCallback, useEffect, useState } from 'react';
import { Alert, Box, Button, Paper, TextField, Typography } from '@mui/material';
import ApiService from '../services/api';
import documentService from '../services/documentService';

interface InformationRequest {
  status: 'open' | 'answered';
  kind: 'details' | 'bill';
  question: string;
  reply?: string;
  documentName?: string;
}

interface RequestRow {
  _id: string;
  description?: string;
  amount?: number;
  currency?: string;
  informationRequest: InformationRequest;
}

const InformationRequestPanel: React.FC = () => {
  const [rows, setRows] = useState<RequestRow[]>([]);
  const [replies, setReplies] = useState<Record<string, string>>({});
  const [files, setFiles] = useState<Record<string, File | null>>({});
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const response = await ApiService.getInformationRequests() as {
        data?: { requests?: RequestRow[] };
      };
      setRows(response?.data?.requests || []);
    } catch (loadError: any) {
      setError(loadError?.message || 'The expert requests could not be loaded.');
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const send = async (row: RequestRow) => {
    const request = row.informationRequest;
    const reply = (replies[row._id] || '').trim();
    const file = files[row._id];
    setBusyId(row._id);
    setError(null);
    setNotice(null);
    try {
      let documentId = '';
      if (request.kind === 'bill' && file) {
        const uploaded = await documentService.uploadDocument(file, 'bill', reply || undefined);
        documentId = uploaded?.document?.id || '';
        if (!documentId) {
          setError('The bill uploaded, but it could not be attached to this transaction.');
          return;
        }
      }
      const response = await ApiService.replyToInformationRequest(row._id, {
        reply,
        documentId: documentId || undefined,
      }) as { message?: string };
      setNotice(response?.message || 'Sent to the expert. They can review this transaction again.');
      await load();
    } catch (sendError: any) {
      setError(sendError?.response?.data?.message || sendError?.message || 'The reply could not be sent.');
    } finally {
      setBusyId(null);
    }
  };

  if (rows.length === 0 && !error && !notice) return null;

  return (
    <Paper variant="outlined" sx={{ p: 2, mb: 2 }}>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 0.5 }}>
        The expert needs more from you
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        A consultant could not calculate carbon from the details already on the transaction. Reply with the missing detail, or upload the bill. The expert reviews that reply and corrects the calculation.
      </Typography>
      {error ? <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert> : null}
      {notice ? <Alert severity="success" sx={{ mb: 2 }} onClose={() => setNotice(null)}>{notice}</Alert> : null}
      {rows.map((row) => {
        const request = row.informationRequest;
        const answered = request.status === 'answered';
        return (
          <Box key={row._id} sx={{ borderTop: 1, borderColor: 'divider', py: 2 }}>
            <Typography variant="subtitle2">{row.description || 'Untitled transaction'}</Typography>
            <Typography variant="body2" color="text.secondary">
              {row.amount != null ? `${row.amount} ${row.currency || 'INR'} · ` : ''}
              {request.kind === 'bill' ? 'Upload the bill' : 'More information'}
            </Typography>
            <Typography variant="body2" sx={{ mt: 0.5 }}>{request.question}</Typography>
            {answered ? (
              <Alert severity="info" sx={{ mt: 1 }}>
                {`Sent to the expert. ${request.reply ? `Your reply: ${request.reply}. ` : ''}${request.documentName ? `Bill: ${request.documentName}.` : ''}`}
              </Alert>
            ) : (
              <Box sx={{ display: 'grid', gap: 1, mt: 1 }}>
                <TextField
                  size="small"
                  label={request.kind === 'bill' ? 'Note for the expert' : 'Your reply'}
                  value={replies[row._id] || ''}
                  onChange={(event) => setReplies((current) => ({ ...current, [row._id]: event.target.value }))}
                />
                {request.kind === 'bill' ? (
                  <Button variant="outlined" component="label">
                    {files[row._id]?.name || 'Choose the bill'}
                    <input
                      hidden
                      type="file"
                      aria-label={`Bill for ${row.description || 'this transaction'}`}
                      onChange={(event) => {
                        const file = event.target.files?.[0] || null;
                        setFiles((current) => ({ ...current, [row._id]: file }));
                      }}
                    />
                  </Button>
                ) : null}
                <Button
                  variant="contained"
                  disabled={
                    busyId === row._id
                    || (
                      (replies[row._id] || '').trim().length < 2
                      && !(request.kind === 'bill' && files[row._id])
                    )
                  }
                  onClick={() => { void send(row); }}
                >
                  {busyId === row._id ? 'Sending' : 'Send to the expert'}
                </Button>
              </Box>
            )}
          </Box>
        );
      })}
    </Paper>
  );
};

export default InformationRequestPanel;
