/**
 * Submission checks for an already chosen clarification prompt.
 * This does not decide which prompt a voucher receives.
 */

const normalizeSpace = (value) => String(value || '').trim().replace(/\s+/g, ' ');

const UNIT_TOKENS = [
  'passenger-km',
  'passenger km',
  'tonne-km',
  'service unit',
  'service_unit',
  'kilometres',
  'kilometers',
  'kilometre',
  'kilometer',
  'litres',
  'liters',
  'litre',
  'liter',
  'tonnes',
  'tonne',
  'hours',
  'hour',
  'nights',
  'night',
  'visits',
  'visit',
  'pieces',
  'piece',
  'meals',
  'meal',
  'kwh',
  'ton',
  'scm',
  'kg',
  'km',
  'm3',
  'gb',
  'gj',
  'bag',
  'set',
  'l'
];

const escapeToken = (token) => token.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/[- ]/g, '[- ]?');

const positiveNumber = (value) => {
  const numeric = Number(normalizeSpace(value));
  return Number.isFinite(numeric) && numeric > 0;
};

const sheetQuantityPhrase = (quantity, unit) => {
  if (!positiveNumber(quantity) || !normalizeSpace(unit)) return '';
  return `${Number(normalizeSpace(quantity))} ${normalizeSpace(unit)}`.toLowerCase();
};

const isQuantityOnlyNote = (note, quantity, unit) => {
  const normalized = normalizeSpace(note).toLowerCase();
  if (!normalized) return false;
  const sheet = sheetQuantityPhrase(quantity, unit);
  if (sheet && normalized === sheet) return true;
  return /^\d+(?:\.\d+)?\s*[a-z][a-z0-9_-]*$/i.test(normalized);
};

const unitInClause = (clause) => {
  const text = normalizeSpace(clause).toLowerCase();
  return UNIT_TOKENS.find((token) => new RegExp(`\\b${escapeToken(token)}\\b`, 'i').test(text)) || '';
};

const parseActivityClause = (clause) => {
  const text = normalizeSpace(clause);
  const quantityMatch = text.match(/-?\d+(?:\.\d+)?/);
  const quantity = quantityMatch ? Number(quantityMatch[0]) : NaN;
  const unit = unitInClause(text);
  let name = text;
  if (quantityMatch) name = name.replace(quantityMatch[0], ' ');
  if (unit) name = name.replace(new RegExp(escapeToken(unit), 'i'), ' ');
  name = name.replace(/[^a-z]+/gi, ' ').trim();
  return {
    name,
    quantity: Number.isFinite(quantity) && quantity > 0 ? quantity : 0,
    unit
  };
};

const compositeListComplete = (note) => {
  const clauses = normalizeSpace(note).split(/\s+and\s+/i).map((part) => part.trim()).filter(Boolean);
  if (clauses.length < 2) return false;
  return clauses.every((clause) => {
    const activity = parseActivityClause(clause);
    return activity.name.length >= 2 && activity.quantity > 0 && Boolean(activity.unit);
  });
};

const materialAnswerAccepted = ({
  promptId,
  requireMaterialName,
  materialName,
  note,
  quantity,
  unit
}) => {
  if (!requireMaterialName) return true;
  if (String(promptId || '') === 'composite_activities') return compositeListComplete(note);
  if (normalizeSpace(materialName)) return true;
  const written = normalizeSpace(note);
  return written.length >= 3 && !isQuantityOnlyNote(written, quantity, unit);
};

module.exports = {
  normalizeSpace,
  positiveNumber,
  isQuantityOnlyNote,
  compositeListComplete,
  materialAnswerAccepted
};
