import React, { useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import ClarificationQueue from '../clarification/ClarificationQueue';
import { clarificationGroupKey, groupClarificationItems } from '../clarification/clarificationModel';
import {
  formatImportAmount,
  formatImportDate,
  type DuplicateAccountingRow,
  type ImportClarificationRequest,
  type InvalidAccountingRow,
  type LastAccountingImportResult,
  type PendingBillUpload,
  type PersistFailureAccountingRow,
} from './accountingImportResult';

export interface ClarificationDraft {
  text: string;
  quantity: string;
  unit: string;
  originAirport: string;
  destinationAirport: string;
  answers: Record<string, string>;
  saved: boolean;
  summary?: string;
}

export interface ClarificationSaveEntry {
  transactionId: string;
  draft: ClarificationDraft;
  body: Record<string, unknown>;
}

type ReviewTone = 'ready' | 'unclear' | 'saved' | 'duplicate' | 'invalid' | 'failed';

interface ReviewRow {
  key: string;
  tone: ReviewTone;
  status: string;
  rowIndex?: number;
  sourceId?: string | null;
  description: string;
  amount?: number;
  date?: string | Date;
  category?: string;
  detail?: string;
  clarification?: ImportClarificationRequest;
}

const PAGE_SIZE = 25;
const DESCRIPTION_CLAMP = 140;

const metricCardSx = {
  minHeight: 58,
  px: 1.25,
  py: 0.75,
  borderRadius: 1.25,
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  minWidth: 0,
} as const;

const metricTrackWidth = (count: number) => ({
  flex: {
    xs: '0 0 calc((100% - 8px) / 2)',
    md: '0 0 calc((100% - 16px) / 3)',
    lg: count > 5 ? '0 0 calc((100% - 40px) / 6)' : '0 0 calc((100% - 32px) / 5)',
  },
  maxWidth: {
    xs: 'calc((100% - 8px) / 2)',
    md: 'calc((100% - 16px) / 3)',
    lg: count > 5 ? 'calc((100% - 40px) / 6)' : 'calc((100% - 32px) / 5)',
  },
});

const MetricCard: React.FC<{ text: string; bgcolor?: string; outlined?: boolean; widthSx?: object }> = ({
  text,
  bgcolor,
  widthSx,
}) => {
  const match = text.match(/^([\d,]+)\s+([\s\S]+)$/);
  const count = match?.[1] ?? text;
  const caption = match?.[2] ?? '';
  return (
    <Box
      sx={{
        ...metricCardSx,
        position: 'relative',
        bgcolor: bgcolor || 'transparent',
        border: '1px solid',
        borderColor: 'divider',
        ...widthSx,
      }}
    >
      <Typography
        component="span"
        sx={{
          position: 'absolute',
          width: 1,
          height: 1,
          p: 0,
          m: -1,
          overflow: 'hidden',
          clip: 'rect(0, 0, 0, 0)',
          whiteSpace: 'nowrap',
          border: 0,
        }}
      >
        {text}
      </Typography>
      <Box aria-hidden="true" sx={{ display: 'flex', flexDirection: 'column' }}>
        <Typography
          component="span"
          sx={{ fontSize: '1.5rem', fontWeight: 700, lineHeight: 1.05, fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.03em' }}
        >
          {count}
        </Typography>
        {caption ? (
          <Typography component="span" variant="caption" color="text.secondary" sx={{ mt: 0.25, lineHeight: 1.25, fontWeight: 600 }}>
            {caption}
          </Typography>
        ) : null}
      </Box>
    </Box>
  );
};

const countLabel = (count: number) => count.toLocaleString('en-IN');

const reviewCountLine = (result: LastAccountingImportResult) => {
  const imported = result.totals.imported;
  const holds = result.totals.pendingBillUpload;
  const parts = [
    result.totals.received != null ? `${countLabel(result.totals.received)} processed` : '',
    `${countLabel(imported)} imported transaction${imported === 1 ? '' : 's'}`,
    holds > 0 ? `${countLabel(holds)} awaiting a bill` : '',
  ].filter(Boolean);
  return `${parts.join('. ')}. Amber rows need a clarification. Saved clarifications stay saved. Carbon calculation starts when you confirm this file. Cancel deletes this uploaded file.`;
};

const toneLabel: Record<ReviewTone, string> = {
  ready: 'Ready',
  unclear: 'Needs clarification',
  saved: 'Clarification saved',
  duplicate: 'Duplicate',
  invalid: 'Invalid',
  failed: 'Failed',
};

interface ImportFileReviewProps {
  result: LastAccountingImportResult;
  drafts: Record<string, ClarificationDraft>;
  deciding: boolean;
  onSaveGroup: (entries: ClarificationSaveEntry[]) => void;
  onConfirm: () => void;
  onCancel: () => void;
}

const ImportFileReview: React.FC<ImportFileReviewProps> = ({
  result,
  drafts,
  deciding,
  onSaveGroup,
  onConfirm,
  onCancel,
}) => {
  const theme = useTheme();
  const [page, setPage] = useState(0);
  const [expandedRows, setExpandedRows] = useState<Record<string, boolean>>({});
  const [queueOpen, setQueueOpen] = useState(false);
  const [openClarificationId, setOpenClarificationId] = useState<string | null>(null);
  const clarifications = useMemo(
    () => result.pendingClarifications || [],
    [result.pendingClarifications],
  );
  const clarificationById = useMemo(() => {
    const map = new Map<string, ImportClarificationRequest>();
    clarifications.forEach((row) => map.set(row.transactionId, row));
    return map;
  }, [clarifications]);
  const billById = useMemo(() => {
    const map = new Map<string, PendingBillUpload>();
    result.pendingBillUpload.forEach((row) => {
      if (row.transactionId) map.set(row.transactionId, row);
    });
    return map;
  }, [result.pendingBillUpload]);

  const isSaved = (transactionId: string, serverSaved?: boolean) => (
    Boolean(drafts[transactionId]?.saved || serverSaved)
  );

  const rows = useMemo(() => {
    const savedRow = (transactionId: string, serverSaved?: boolean) => (
      Boolean(drafts[transactionId]?.saved || serverSaved)
    );
    const importedRows: ReviewRow[] = result.imported.map((row, index) => {
      const id = row.id ? String(row.id) : '';
      const clarification = id ? clarificationById.get(id) : undefined;
      const bill = id ? billById.get(id) : undefined;
      const saved = clarification
        ? savedRow(clarification.transactionId, clarification.clarificationSaved)
        : false;
      let tone: ReviewTone = 'ready';
      let status = 'Ready';
      if (clarification && !saved) {
        tone = 'unclear';
        status = toneLabel.unclear;
      } else if (clarification && saved) {
        tone = 'saved';
        status = toneLabel.saved;
      } else if (bill) {
        status = 'Bill can be added later';
      }
      return {
        key: id || row.sourceId || `imported-${row.rowIndex ?? index}`,
        tone,
        status,
        rowIndex: row.rowIndex,
        sourceId: row.sourceId,
        description: clarification?.description || row.description || 'No description',
        amount: row.amount,
        date: row.date,
        category: row.category,
        clarification,
      };
    });
    const importedIds = new Set(result.imported.map((row) => (row.id ? String(row.id) : '')).filter(Boolean));
    const missingClarifications: ReviewRow[] = clarifications
      .filter((row) => !importedIds.has(row.transactionId))
      .map((row) => ({
        key: `clarify-${row.transactionId}`,
        tone: (savedRow(row.transactionId, row.clarificationSaved) ? 'saved' : 'unclear') as ReviewTone,
        status: savedRow(row.transactionId, row.clarificationSaved) ? toneLabel.saved : toneLabel.unclear,
        rowIndex: row.rowIndex ?? undefined,
        sourceId: row.sourceId,
        description: row.description || row.title || 'Unclear transaction',
        amount: row.amount,
        date: row.date || undefined,
        category: row.category,
        clarification: row,
      }));
    const extras: ReviewRow[] = [
      ...result.duplicates.map((row, index) => problemRow('duplicate', row, index, (row.reasons || []).join('; '))),
      ...result.invalidRows.map((row, index) => problemRow('invalid', row, index, (row.errors || []).join('; '))),
      ...result.persistFailures.map((row, index) => problemRow('failed', row, index, row.error || '')),
    ];
    return [...missingClarifications, ...importedRows, ...extras];
  }, [billById, clarificationById, clarifications, drafts, result]);

  const unclearCount = clarifications.filter((row) => !isSaved(row.transactionId, row.clarificationSaved)).length;
  const savedCount = clarifications.filter((row) => isSaved(row.transactionId, row.clarificationSaved)).length;
  const openItems = useMemo(
    () => clarifications.filter((row) => !drafts[row.transactionId]?.saved && row.clarificationSaved !== true),
    [clarifications, drafts]
  );
  const groupProgress = useMemo(() => {
    const allGroups = groupClarificationItems(clarifications);
    const openKeys = new Set(groupClarificationItems(openItems).map((group) => group.key));
    return {
      completedGroupCount: allGroups.filter((group) => !openKeys.has(group.key)).length,
      totalGroupCount: allGroups.length,
      ordinalByKey: Object.fromEntries(allGroups.map((group, index) => [group.key, index + 1])),
    };
  }, [clarifications, openItems]);
  const preferredKey = useMemo(() => {
    const match = openItems.find((row) => row.transactionId === openClarificationId);
    return match ? clarificationGroupKey(match) : null;
  }, [openClarificationId, openItems]);
  const pageRows = rows.slice(page * PAGE_SIZE, page * PAGE_SIZE + PAGE_SIZE);
  const importedMetric = result.imported.length < result.totals.imported
    ? `${countLabel(result.imported.length)} shown of ${countLabel(result.totals.imported)} imported`
    : `${countLabel(result.totals.imported)} imported`;
  const showAwaitingBill = result.totals.pendingBillUpload > 0;
  const metricWidth = metricTrackWidth(showAwaitingBill ? 6 : 5);
  const toneColor = (tone: ReviewTone) => {
    if (tone === 'unclear') return theme.palette.warning.main;
    if (tone === 'saved') return theme.palette.info.main;
    if (tone === 'duplicate') return theme.palette.text.secondary;
    if (tone === 'ready') return theme.palette.divider;
    return theme.palette.error.main;
  };

  return (
    <Box
      component="section"
      aria-label="Imported transactions"
      sx={{ mb: 3, minWidth: 0 }}
    >
      <Box sx={{ mb: 1.5, pb: 1.5, borderBottom: '1px solid', borderColor: 'divider' }}>
        <Typography variant="overline" color="text.secondary" sx={{ display: 'block', letterSpacing: '0.12em', fontWeight: 700, lineHeight: 1.2 }}>
          Import review
        </Typography>
        <Typography variant="h6" component="h2" sx={{ mt: 0.5, fontWeight: 700, letterSpacing: '-0.02em', lineHeight: 1.3, wordBreak: 'break-word' }}>
          {result.fileName}
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 0.75, maxWidth: '72ch', lineHeight: 1.45 }}>
          {reviewCountLine(result)}
        </Typography>
      </Box>
      <Box
        sx={{
          display: 'flex',
          flexWrap: 'wrap',
          justifyContent: 'center',
          gap: 1,
          mb: 2,
        }}
      >
        <MetricCard text={importedMetric} bgcolor={alpha(theme.palette.success.main, 0.15)} widthSx={metricWidth} />
        {showAwaitingBill ? (
          <MetricCard
            text={`${countLabel(result.totals.pendingBillUpload)} awaiting bill`}
            bgcolor={alpha(theme.palette.warning.main, 0.16)}
            widthSx={metricWidth}
          />
        ) : null}
        <MetricCard text={`${unclearCount} need clarification`} bgcolor={alpha(theme.palette.warning.main, 0.22)} widthSx={metricWidth} />
        <MetricCard text={`${savedCount} clarification saved`} bgcolor={alpha(theme.palette.info.main, 0.16)} widthSx={metricWidth} />
        <MetricCard text={`${countLabel(result.totals.duplicates)} duplicate`} outlined widthSx={metricWidth} />
        <MetricCard
          text={`${countLabel(result.totals.invalid + result.totals.persistFailures)} invalid or failed`}
          bgcolor={alpha(theme.palette.error.main, 0.12)}
          widthSx={metricWidth}
        />
      </Box>
      {unclearCount > 0 && (
        <Alert severity="warning" sx={{ mb: 1.5 }}>
          Highlighted rows are unclear. Add clarifications once for each group of matching vouchers. Cancel deletes the uploaded file.
        </Alert>
      )}
      {queueOpen && openItems.length > 0 ? (
        <Box sx={{ mb: 1.5 }}>
          <ClarificationQueue
            items={openItems}
            saving={deciding}
            preferredKey={preferredKey}
            completedGroupCount={groupProgress.completedGroupCount}
            totalGroupCount={groupProgress.totalGroupCount}
            ordinalByKey={groupProgress.ordinalByKey}
            onSubmitGroup={(entries) => {
              onSaveGroup(entries.map(({ item, body }) => {
                const saved = body as Record<string, unknown>;
                return {
                  transactionId: item.transactionId,
                  body: saved,
                  draft: {
                    text: String(saved.transactionClarification || ''),
                    quantity: saved.quantity == null ? String(item.quantity || '') : String(saved.quantity),
                    unit: String(saved.unit || item.unit || ''),
                    originAirport: String(saved.originAirport || ''),
                    destinationAirport: String(saved.destinationAirport || ''),
                    answers: Object.fromEntries(
                      Object.entries(saved).flatMap(([key, value]) => {
                        if ([
                          'carbonInputBasis',
                          'quantity',
                          'unit',
                          'transactionClarification',
                          'clarificationWithoutBill',
                          'materialName',
                          'originAirport',
                          'destinationAirport',
                        ].includes(key) || !String(value ?? '').trim()) return [];
                        return [[key, String(value)]];
                      })
                    ),
                    saved: true,
                    summary: String(saved.transactionClarification || ''),
                  },
                };
              }));
            }}
          />
        </Box>
      ) : null}
      {rows.length === 0 ? (
        <Alert severity="info" sx={{ mb: 1.5 }}>
          {result.totals.imported > 0
            ? `${result.totals.imported.toLocaleString('en-IN')} transactions were imported. Row details were not included in this response.`
            : 'No transaction rows were returned for this file.'}
        </Alert>
      ) : (
        <TableContainer sx={{ maxHeight: { xs: 520, md: 640 }, border: 1, borderColor: 'divider', borderRadius: 2, width: '100%', minWidth: 0, maxWidth: '100%', overflowX: 'auto', WebkitOverflowScrolling: 'touch', bgcolor: 'background.paper' }}>
          <Table size="small" stickyHeader sx={{ minWidth: 760 }}>
            <TableHead>
              <TableRow>
                <TableCell sx={{ width: 168, py: 1.25 }}>Status</TableCell>
                <TableCell sx={{ width: 72, py: 1.25 }}>Row</TableCell>
                <TableCell sx={{ py: 1.25 }}>Transaction</TableCell>
                <TableCell align="right" sx={{ width: 128, py: 1.25 }}>Amount</TableCell>
                <TableCell sx={{ width: 112, py: 1.25 }}>Date</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {pageRows.map((row) => {
                const draft = row.clarification ? drafts[row.clarification.transactionId] : undefined;
                const descriptionOpen = Boolean(expandedRows[row.key]);
                const descriptionLong = row.description.length > DESCRIPTION_CLAMP;
                return (
                  <TableRow
                    key={row.key}
                    sx={{
                      bgcolor: row.tone === 'ready'
                        ? 'transparent'
                        : alpha(toneColor(row.tone), 0.16),
                      '& td': { verticalAlign: 'top', py: 1.25 },
                    }}
                  >
                    <TableCell sx={{ whiteSpace: 'nowrap' }}>
                      <Chip
                        size="small"
                        label={row.status}
                        sx={{ bgcolor: alpha(toneColor(row.tone), 0.2), fontWeight: 600 }}
                      />
                    </TableCell>
                    <TableCell sx={{ fontVariantNumeric: 'tabular-nums' }}>{row.rowIndex ?? '—'}</TableCell>
                    <TableCell sx={{ minWidth: 220 }}>
                      <Typography
                        variant="body2"
                        sx={{
                          fontWeight: 700,
                          lineHeight: 1.4,
                          wordBreak: 'break-word',
                          ...(descriptionLong && !descriptionOpen ? {
                            display: '-webkit-box',
                            WebkitLineClamp: 2,
                            WebkitBoxOrient: 'vertical',
                            overflow: 'hidden',
                          } : {}),
                        }}
                      >
                        {row.description}
                      </Typography>
                      {descriptionLong ? (
                        <Button
                          type="button"
                          size="small"
                          color="inherit"
                          onClick={() => setExpandedRows((prev) => ({ ...prev, [row.key]: !prev[row.key] }))}
                          sx={{ mt: 0.25, px: 0, minWidth: 0, fontWeight: 600 }}
                        >
                          {descriptionOpen ? 'Show less' : 'Show full description'}
                        </Button>
                      ) : null}
                      <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.25 }}>
                        {[row.category, row.sourceId].filter(Boolean).join(' · ') || '—'}
                      </Typography>
                      {row.clarification && (row.clarification.originalQuantity !== undefined || row.clarification.originalUnit !== undefined) ? (
                        <Typography variant="caption" color="text.secondary" display="block">
                          {`Original quantity: ${row.clarification.originalQuantity || 'Not in the uploaded file'} ${row.clarification.originalUnit || ''}`.trim()}
                        </Typography>
                      ) : null}
                      {row.detail ? (
                        <Typography variant="caption" color="text.secondary" display="block">{row.detail}</Typography>
                      ) : null}
                      {draft?.saved && draft.summary ? (
                        <Typography variant="caption" color="text.secondary" display="block">
                          {draft.summary}
                        </Typography>
                      ) : null}
                      {row.clarification && !isSaved(row.clarification.transactionId, row.clarification.clarificationSaved) ? (
                        <Button
                          size="small"
                          variant="outlined"
                          color="warning"
                          sx={{ mt: 1 }}
                          disabled={deciding}
                          onClick={() => {
                            setOpenClarificationId(row.clarification!.transactionId);
                            setQueueOpen(true);
                          }}
                        >
                          Add clarifications
                        </Button>
                      ) : null}
                    </TableCell>
                    <TableCell align="right" sx={{ whiteSpace: 'nowrap', fontVariantNumeric: 'tabular-nums', fontWeight: 600 }}>
                      {formatImportAmount(row.amount)}
                    </TableCell>
                    <TableCell sx={{ whiteSpace: 'nowrap', fontVariantNumeric: 'tabular-nums' }}>{formatImportDate(row.date)}</TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>
      )}
      {rows.length > PAGE_SIZE ? (
        <TablePagination
          component="div"
          count={rows.length}
          page={page}
          rowsPerPage={PAGE_SIZE}
          rowsPerPageOptions={[PAGE_SIZE]}
          onPageChange={(_event, nextPage) => setPage(nextPage)}
          sx={{
            border: 1,
            borderColor: 'divider',
            borderTop: 0,
            borderRadius: '0 0 8px 8px',
            mt: -0.25,
            '& .MuiTablePagination-toolbar': {
              flexWrap: 'wrap',
              justifyContent: { xs: 'center', sm: 'flex-end' },
              minHeight: 52,
              px: { xs: 1, sm: 2 },
            },
          }}
        />
      ) : null}
      <Stack
        data-testid="import-review-actions"
        direction={{ xs: 'column', sm: 'row' }}
        spacing={1}
        sx={{
          mt: 2,
          py: 1.5,
          px: { xs: 0, sm: 0.5 },
          borderTop: '1px solid',
          borderColor: 'divider',
          bgcolor: 'background.paper',
          alignItems: { sm: 'center' },
        }}
      >
        <Button
          variant="contained"
          color="success"
          onClick={onConfirm}
          disabled={deciding || unclearCount > 0}
        >
          {unclearCount > 0
            ? `Confirm and calculate (${unclearCount} still need clarification)`
            : 'Confirm and calculate'}
        </Button>
        <Button variant="outlined" color="error" onClick={onCancel} disabled={deciding}>
          Cancel
        </Button>
        {unclearCount > 0 ? (
          <Typography variant="caption" color="text.secondary" sx={{ flexBasis: { sm: '100%' } }}>
            {`Confirm and calculate stays off until the remaining ${unclearCount} clarification${unclearCount === 1 ? ' is' : 's are'} saved.`}
          </Typography>
        ) : null}
      </Stack>
    </Box>
  );
};

const problemRow = (
  tone: Extract<ReviewTone, 'duplicate' | 'invalid' | 'failed'>,
  row: DuplicateAccountingRow | InvalidAccountingRow | PersistFailureAccountingRow,
  index: number,
  detail: string
): ReviewRow => ({
  key: `${tone}-${row.sourceId || row.rowIndex || index}`,
  tone,
  status: toneLabel[tone],
  rowIndex: row.rowIndex,
  sourceId: row.sourceId,
  description: row.sourceId || `Row ${row.rowIndex ?? index + 1}`,
  detail,
});

export default ImportFileReview;
