import React, { useEffect, useRef, useState } from 'react';
import {
  Alert,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  Typography,
} from '@mui/material';
import ClarificationQueue, { type ClarificationSubmission } from './clarification/ClarificationQueue';
import {
  buildClarificationAnswer,
  type ClarificationAnswerDraft,
  type ClarificationQueueItem,
} from './clarification/clarificationModel';

export interface UncertaintyClarificationField {
  id: string;
  metadataField: string;
  label: string;
  kind?: 'choice' | 'number' | 'text';
  required?: boolean;
  options?: Array<{ value: string; label: string }>;
}

export interface UncertaintyClarificationQuestion extends ClarificationQueueItem {
  transactionId: string;
}

export interface IdentifiedSpendPrice {
  transactionId: string;
  description?: string;
  amount?: number;
  priceInr: number;
  priceLabel: string;
  factorId: string;
  citation?: string;
  co2Emissions?: number | null;
  formula?: string;
}

export const buildUncertaintyAnswer = (
  question: UncertaintyClarificationQuestion,
  draft: ClarificationAnswerDraft
) => buildClarificationAnswer(question, draft);

export interface UncertaintyAnswerEntry {
  question: UncertaintyClarificationQuestion;
  body: ReturnType<typeof buildUncertaintyAnswer>;
}

interface UncertaintyClarificationAgentDialogProps {
  open: boolean;
  loading: boolean;
  saving: boolean;
  error: string | null;
  questions: UncertaintyClarificationQuestion[];
  identifiedPrices?: IdentifiedSpendPrice[];
  onClose: () => void;
  onSubmit?: (question: UncertaintyClarificationQuestion, body: ReturnType<typeof buildUncertaintyAnswer>) => void;
  onSubmitGroup?: (entries: UncertaintyAnswerEntry[]) => void;
  onUndoIdentified?: (row: IdentifiedSpendPrice) => void;
}

const priceLine = (row: IdentifiedSpendPrice) => {
  const emissions = row.co2Emissions != null ? ` (${Number(row.co2Emissions).toFixed(2)} kg CO2e)` : '';
  return `${row.description || 'This voucher'} uses ${row.priceLabel} ${row.priceInr}. Carbon uses (spend amount ÷ unit price) × the emission factor${emissions}.`;
};

const UncertaintyClarificationAgentDialog: React.FC<UncertaintyClarificationAgentDialogProps> = ({
  open,
  loading,
  saving,
  error,
  questions,
  identifiedPrices = [],
  onClose,
  onSubmit,
  onSubmitGroup,
  onUndoIdentified,
}) => {
  const wasOpen = useRef(false);
  const [resetToken, setResetToken] = useState(0);

  useEffect(() => {
    if (open && !wasOpen.current) setResetToken((token) => token + 1);
    wasOpen.current = open;
  }, [open]);

  const submitGroup = (entries: ClarificationSubmission[]) => {
    const mapped = entries.flatMap((entry) => {
      const question = questions.find((item) => item.transactionId === entry.item.transactionId);
      return question ? [{ question, body: entry.body }] : [];
    });
    if (mapped.length === 0) return;
    if (onSubmitGroup) {
      onSubmitGroup(mapped);
      return;
    }
    mapped.forEach((entry) => onSubmit?.(entry.question, entry.body));
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      keepMounted
      aria-labelledby="uncertainty-agent-title"
    >
      <DialogTitle id="uncertainty-agent-title">Carbon clarification agent</DialogTitle>
      <DialogContent>
        <Stack spacing={1.5} sx={{ mt: 1 }}>
          {!loading && identifiedPrices.length > 0 ? (
            <Alert severity="success">
              <Stack spacing={1}>
                {identifiedPrices.map((row) => (
                  <Stack
                    key={row.transactionId}
                    direction={{ xs: 'column', sm: 'row' }}
                    spacing={1}
                    sx={{ alignItems: { sm: 'center' }, justifyContent: 'space-between' }}
                  >
                    <Typography variant="body2">{priceLine(row)}</Typography>
                    {onUndoIdentified ? (
                      <Button
                        size="small"
                        disabled={saving}
                        onClick={() => onUndoIdentified(row)}
                        aria-label={`Undo cited price for ${row.description || 'this voucher'}`}
                      >
                        Undo
                      </Button>
                    ) : null}
                  </Stack>
                ))}
              </Stack>
            </Alert>
          ) : null}
          {!loading && questions.length === 0 && identifiedPrices.length === 0 ? (
            <Alert severity="success">No uncertain quantities need an answer.</Alert>
          ) : null}
          {questions.length > 0 ? (
            <ClarificationQueue
              items={questions}
              loading={loading}
              saving={saving}
              resetToken={resetToken}
              onSubmitGroup={submitGroup}
            />
          ) : null}
          {error ? <Alert severity="error">{error}</Alert> : null}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={saving}>Close</Button>
      </DialogActions>
    </Dialog>
  );
};

export default UncertaintyClarificationAgentDialog;
